#!/usr/bin/env python3
"""Reconstruct the exact standalone v308 from the unchanged v210.
Does not execute a solver or register any evaluation. The payload contains
only line edits; generated C++ and the accompanying patch are readable.
"""
from pathlib import Path
import base64,hashlib,json,zlib,difflib
ROOT=Path(__file__).resolve().parents[2]
PARENT='4be4bd07bee152643fe4620f50573764a5a74167a81d5f9c280f0655789feaed'
EXPECTED='2543cbd9610ba4809c1f3b2a3e44099cb6cd2c3af38b9fba61c8f0ccc287b133'
PAYLOAD=''

def main():
    parent=ROOT/'src/bin/v210_collection_color_quotient.cpp'
    data=parent.read_bytes()
    if hashlib.sha256(data).hexdigest()!=PARENT:
        raise SystemExit('Parent hash mismatch; refusing to edit a different v210')
    original=data.decode('utf-8');lines=original.splitlines(True)
    edits=json.loads(zlib.decompress(base64.b64decode(PAYLOAD)))
    for first,last,replacement in reversed(edits):lines[first:last]=replacement
    result=''.join(lines).encode('utf-8')
    if hashlib.sha256(result).hexdigest()!=EXPECTED:
        raise SystemExit('Generated source hash mismatch')
    destination=ROOT/'src/bin/v308_local_cohesion.cpp'
    if destination.exists() and destination.read_bytes()!=result:
        raise SystemExit('Refusing to overwrite a different v308')
    destination.write_bytes(result)
    patch=ROOT/'adhoc/v308/v308_vs_v210.patch';patch.parent.mkdir(parents=True,exist_ok=True)
    patch.write_text(''.join(difflib.unified_diff(original.splitlines(True),result.decode().splitlines(True),fromfile='a/src/bin/v210_collection_color_quotient.cpp',tofile='b/src/bin/v308_local_cohesion.cpp')))
    print(destination,EXPECTED)
if __name__=='__main__':main()
